from math import comb

def f_Kn(n):
    # Number of triangles (C3) in Kn
    if n < 3:
        return 0
    return comb(n, 3)

def g_Kn(n):
    # Number of C4 subgraphs in Kn (3 * C(n, 4))
    if n < 4:
        return 0
    # g(Kn) = 3 * C(n, 4) = n(n-1)(n-2)(n-3) / 8
    return n * (n-1) * (n-2) * (n-3) // 8

def calculate_ratio(n):
    f = f_Kn(n)
    g = g_Kn(n)
    if f == 0:
        return "Undefined (f=0)"
    return (g**3) / (f**4)

print("N | f(Kn) | g(Kn) | Ratio")
print("-" * 30)
for n in range(3, 9):
    ratio = calculate_ratio(n)
    if isinstance(ratio, float):
        print(f"{n} | {f_Kn(n)} | {g_Kn(n)} | {ratio:.6f}")
    else:
        print(f"{n} | {f_Kn(n)} | {g_Kn(n)} | {ratio}")

import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def R_Kn(n):
    if n < 4:
        return 0 # Or handle division by zero case, but for small n, the ratio is often undefined or zero if g=0.

    f_Kn = combinations(n, 3)
    g_Kn = combinations(n, 4)

    if f_Kn == 0:
        # This should only happen for n < 3, but included for robustness
        return float('inf') 

    return (g_Kn**3) / (f_Kn**4)

# Verify the trend for small n
n_values = range(4, 16)
results = {n: R_Kn(n) for n in n_values}

print("n | R(K_n)")
for n, r in results.items():
    print(f"{n:2} | {r}")
